def api_tool(name, path, data_fields, desc, pre, post, retries=0, required=None):
    return {
        "type": "function",
        "config": {"timeoutMs": 20000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": MOCK + path},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "required": ["data"], "properties": {
                    "data": {"type": "object", "properties": data_fields, "required": required or []},
                    "call": {"type": "object", "properties": {"ani": {"type": "string", "default": ""}, "lang": {"type": "string", "default": "tr"}}}}}}}},
        "pre_process_code": pre,
        "post_process_code": post,
    }

