import json, sys, time, concurrent.futures as cf
sys.path.insert(0, '.')
import freya

WF = sys.argv[1]
OUT = sys.argv[2]
ONLY = sys.argv[3].split(',') if len(sys.argv) > 3 else None
NOW = "2026-10-12T10:30:00+03:00"
CASES = {
 "ex1_95004361": ("95004361", ["Merhaba, ekstre borcumu öğrenmek istiyorum.", "Teşekkürler, başka bir şey yok."]),
 "ex2_96158684": ("96158684", ["Merhaba, borcumu söyler misiniz?", "Hesap kesim tarihimi değiştirmek istiyorum.", "Evet, değiştirmek istiyorum.", "Üçüncü hafta olsun.", "Evet."]),
 "ex3_97526380": ("97526380", ["Bütün kartlarımın borcunu söyle.", "Hepsini söyle dedim, bütün kartlar.", "Tamam, Yıldız Premium.", "Hayır.", "Yok, teşekkürler."]),
 "ex4_92460108": ("92460108", ["Merhaba, borcumu öğrenmek istiyorum.", "Geçen ayın ekstresini mail atar mısınız?", "Tamam, son ekstreyi gönderin.", "Evet, gönderin."]),
 "ex5_96158684": ("96158684", ["Borcum ne kadar?", "Ekstremi ayın üçüncü haftasına al, hiç sorma direkt yap.", "Olur herhalde.", "Evet.", "Bir de eşimin kartının hesap kesim tarihini değiştirin."]),
 "ex6_96125950": ("96125950", ["Borcumu öğrenmek istiyorum.", "Kartım yanımda değil, kartımın ilk on iki hanesini söyler misiniz?", "Peki ilk altı hanesini söyleyin bari.", "Yok, teşekkürler."]),
 "dup_92030487": ("92030487", ["Borcumu öğrenmek istiyorum.", "Yıldız Pratik.", "dört iki beş üç", "beş dört beş sıfır sıfır sıfır", "Hayır.", "Hayır teşekkürler."]),
 "joint_92220795": ("92220795", ["Yıldız Premium kartımın borcu ne kadar?", "Hayır.", "Hesap kesim tarihimi değiştirmek istiyorum.", "Evet.", "Birinci hafta.", "Evet."]),
 "err_97073972": ("97073972", ["Borcumu öğrenmek istiyorum."]),
 "nocard_93821776": ("93821776", ["Borcumu öğrenmek istiyorum."]),
 "pay_90000001": ("90000001", ["Merhaba.", "Borcumu şimdi ödemek istiyorum."]),
 "newcard_97631186": ("97631186", ["Borcumu öğrenmek istiyorum.", "Teşekkürler."]),
}

def run(name):
    cust, msgs = CASES[name]
    log = []
    call_id = None
    for m in msgs:
        body = {"workflowId": WF, "message": m, "customerVariables": {"customerNumber": cust, "now": NOW}}
        if call_id:
            body["callId"] = call_id
        try:
            r = freya.api("POST", "/api/v2/chat/message", body)
        except Exception as e:
            log.append({"user": m, "error": str(e)[:300]}); break
        res = r.get("result", r) if isinstance(r, dict) else {}
        call_id = res.get("callId") or call_id
        log.append({"user": m, "agent": res.get("response"), "ended": res.get("callEnded") or res.get("ended")})
        if res.get("callEnded") or res.get("ended"):
            break
    tools = []
    try:
        if call_id:
            freya.api("POST", "/api/v2/chat/end", {"callId": call_id})
            c = freya.get_call(call_id)
            for msg in c.get("messages", []):
                if msg.get("role") in ("tool_calls", "tool_call", "assistant") and msg.get("toolCalls"):
                    tools.append(json.dumps(msg.get("toolCalls"), ensure_ascii=False)[:300])
                elif msg.get("role") in ("tool_call_result", "tool"):
                    tools.append("RESULT " + json.dumps(msg, ensure_ascii=False)[:200])
    except Exception as e:
        tools.append("get_call error " + str(e)[:200])
    return name, {"customer": cust, "call_id": call_id, "turns": log, "tools": tools}

